Hier ist ein Beispiel-C++ Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    // Eingabe von Dateiname und Suchwort
    string filename;
    cout << "Enter filename: ";
    cin >> filename;

    string search_word;
    cout << "Enter search word: ";
    cin >> search_word;

    // Öffnen der Datei
    ifstream file(filename);
    if (!file) {
        cerr << "Error: Unable to open file." << endl;
        return 1;
    }

    // Wörterbuch für Vorkommen von Suchwort
    unordered_map<string, int> word_count;

    // Zeilen lesen und Suchwort zählen
    string line;
    while (getline(file, line)) {
        // Zeilenweise lesen und Suchwort finden
        size_t pos = 0;
        string token;
        while ((pos = line.find(search_word, pos)) != string::npos) {
            // Suchwort gefunden, Wortzähler erhöhen
            pos += search_word.length(); // Sprung nach dem Suchwort
            token = search_word; // Suchwort als Token setzen
            if (word_count.find(token) != word_count.end()) {
                word_count[token]++;
            } else {
                word_count[token] = 1;
            }
        }
    }

    // Ausgabe der Anzahl der Vorkommen des Suchworts
    int count = word_count[search_word];
    cout << "The word '" << search_word << "' appears " << count << " times in " << filename << "." << endl;

    // Schließen der Datei
    file.close();

    return 0;
}
```

